export function winScreenPresentation(age: number) {
  const contentFrame = age < 40 ? 1 : Math.min(25, age - 38);
  return {
    contentFrame,
    alpha: age < 40 ? 0 : WIN_SCREEN.fade[contentFrame - 1],
    blurPasses: Math.floor(Math.min(age, 39) / 2),
  };
}

